const assets = {"/index.html":{"type":"text/html; charset=utf-8","data":""},"/styles.css":{"type":"text/css; charset=utf-8","data":""},"/script.js":{"type":"text/javascript; charset=utf-8","data":""},"/assets/cv-andrea-rodriguez.txt":{"type":"text/plain; charset=utf-8","data":""},"/assets/llave-publica-andrea.asc":{"type":"application/pgp-keys; charset=utf-8","data":"LS0tLS1CRUdJTiBQR1AgUFVCTElDIEtFWSBCTE9DSy0tLS0tCgpERU1PLU9OTFktUkVQTEFDRS1XSVRILVlPVVItUkVBTC1QVUJMSUMtS0VZCkVzdGUgYXJjaGl2byBlcyB1biBtYXJjYWRvciBkZSBwb3NpY2nDs24geSBubyBjb250aWVuZSB1bmEgbGxhdmUgZnVuY2lvbmFsLgoKLS0tLS1FTkQgUEdQIFBVQkxJQyBLRVkgQkxPQ0stLS0tLQo="},"/assets/og.png":{"type":"image/png","data":""}};

const securityHeaders = {
  'content-security-policy': "default-src 'self'; style-src 'self'; script-src 'self'; img-src 'self' data:; font-src 'self'; connect-src 'self'; object-src 'none'; base-uri 'self'; frame-ancestors 'none'",
  'referrer-policy': 'strict-origin-when-cross-origin',
  'x-content-type-options': 'nosniff',
  'x-frame-options': 'DENY',
};

const decode = (value) => Uint8Array.from(atob(value), (character) => character.charCodeAt(0));

export default {
  async fetch(request) {
    const url = new URL(request.url);
    const route = url.pathname === '/' ? '/index.html' : url.pathname.replace(/\/$/, '');
    const asset = assets[route];

    if (!asset) {
      return new Response('Página no encontrada', { status: 404, headers: securityHeaders });
    }

    let body = decode(asset.data);
    if (route === '/index.html') {
      body = new TextDecoder().decode(body).replaceAll('__SITE_ORIGIN__', url.origin);
    }

    const headers = new Headers(securityHeaders);
    headers.set('content-type', asset.type);
    headers.set('cache-control', route === '/index.html' ? 'no-cache' : 'public, max-age=86400');
    return new Response(body, { headers });
  },
};
